<?php

namespace App\Restaurant\Repository;
use Doctrine\ORM\EntityRepository;
use App\Tool\Entity\GlobalOption;

/**
 * DmsConfigRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class RestaurantConfigRepository extends EntityRepository
{


    public function reset(GlobalOption $option)
    {

        $em = $this->getEntityManager();
        $config = $option->getRestaurantConfig()->getId();

        $history = $em->createQuery('DELETE App\Restaurant\Entity\RestaurantStockHistory e WHERE e.restaurantConfig = '.$config);
        $history->execute();

        $batch = $em->createQuery('DELETE App\Restaurant\Entity\ProductionBatch e WHERE e.restaurantConfig = '.$config);
        $batch->execute();

        $invoice = $em->createQuery('DELETE App\Restaurant\Entity\Invoice e WHERE e.restaurantConfig = '.$config);
        $invoice->execute();

        $purchase = $em->createQuery('DELETE App\Restaurant\Entity\Purchase e WHERE e.restaurantConfig = '.$config);
        $purchase->execute();

        $elem = "UPDATE `restaurant_particular` as sub
                 SET sub.openingQuantity = '', sub.quantity = '', sub.productionQuantity = '', sub.purchaseQuantity = '', sub.purchaseQuantity = '', sub.salesQuantity = '', sub.damageQuantity = '', sub.purchaseReturnQuantity = '', sub.remainingQuantity = ''
                 WHERE sub.restaurantConfig_id =:config";
        $qb1 = $this->getEntityManager()->getConnection()->prepare($elem);
        $qb1->bindValue('config', $config);
        $qb1 = $qb1->executeQuery();

    }

    public function delete(GlobalOption $option)
    {

        $em = $this->getEntityManager();
        $config = $option->getRestaurantConfig()->getId();

        $history = $em->createQuery('DELETE App\Restaurant\Entity\RestaurantStockHistory e WHERE e.restaurantConfig = '.$config);
        $history->execute();

        $batch = $em->createQuery('DELETE App\Restaurant\Entity\ProductionBatch e WHERE e.restaurantConfig = '.$config);
        $batch->execute();

        $invoice = $em->createQuery('DELETE App\Restaurant\Entity\Invoice e WHERE e.restaurantConfig = '.$config);
        $invoice->execute();

        $purchase = $em->createQuery('DELETE App\Restaurant\Entity\Purchase e WHERE e.restaurantConfig = '.$config);
        $purchase->execute();

        $purchase = $em->createQuery('DELETE App\Restaurant\Entity\ItemImport e WHERE e.restaurantConfig = '.$config);
        $purchase->execute();

        $Particular = $em->createQuery('DELETE App\Restaurant\Entity\Particular e WHERE e.restaurantConfig = '.$config);
        $Particular->execute();

        $purchase = $em->createQuery('DELETE App\Restaurant\Entity\Category e WHERE e.restaurantConfig = '.$config);
        $purchase->execute();



    }

    public function resetPurchaseSalesProduction(GlobalOption $option)
    {

        $em = $this->getEntityManager();
        $config = $option->getRestaurantConfig ()->getId();

        $history = $em->createQuery('DELETE App\Restaurant\Entity\RestaurantStockHistory e WHERE e.restaurantConfig = '.$config);
        $history->execute();

        $batch = $em->createQuery('DELETE App\Restaurant\Entity\ProductionBatch e WHERE e.restaurantConfig = '.$config);
        $batch->execute();

        $invoice = $em->createQuery('DELETE App\Restaurant\Entity\Invoice e WHERE e.restaurantConfig = '.$config);
        $invoice->execute();

        $purchase = $em->createQuery('DELETE App\Restaurant\Entity\Purchase e WHERE e.restaurantConfig = '.$config);
        $purchase->execute();

        $ids = $this->createQueryBuilder('')
            ->from(\App\Restaurant\Entity\Invoice::class,'e')
            ->where("e.restaurantConfig={$config}")
            ->select('e.id')
            ->getQuery()->getResult();

        $this->createQueryBuilder('product')
            ->from('Restaurant/InvoiceItem','product')
            ->where('product.id in (:ids)')
            ->setParameter('ids', $ids)
            ->delete()
            ->getQuery()
            ->execute();


        $elem = "UPDATE `restaurant_particular` as sub
                 SET sub.openingQuantity = '', sub.quantity = '', sub.productionQuantity = '', sub.purchaseQuantity = '', sub.purchaseQuantity = '', sub.salesQuantity = '', sub.damageQuantity = '', sub.purchaseReturnQuantity = '', sub.remainingQuantity = ''
                 WHERE sub.restaurantConfig_id =:config";
        $qb1 = $this->getEntityManager()->getConnection()->prepare($elem);
        $qb1->bindValue('config', $config);
        $qb1 = $qb1->executeQuery();

    }


    public function invoiceDelete($config)
    {
        $em = $this->getEntityManager();
        $cid = $config->getId();
        $Invoice = $em->createQuery("DELETE App\\Restaurant\\Entity\\Invoice e WHERE  e.process = 'Created' and e.restaurantConfig = ".$cid);
        $Invoice->execute();

    }
}
